mapper.select:
SELECT COUNT(DISTINCT user_name)
FROM table_access_user_daily
WHERE cluster_id = #{clusterId}
  AND db_name = #{dbName}
  AND table_name = #{tableName}
  AND access_date >= #{startDate}

SELECT user_name AS user_id,
       SUM(access_count) AS access_count,
       MAX(last_access_time) AS last_access_time
FROM table_access_user_daily
WHERE cluster_id = #{clusterId}
  AND db_name = #{dbName}
  AND table_name = #{tableName}
  AND access_date >= #{startDate}
GROUP BY user_name
ORDER BY access_count DESC, user_name
LIMIT #{limit}
